import heapq

Graph = dict[str, dict[str, int]]


def dijkstra(graph: Graph, src: str, dest: str) -> list[str]:
    distances: dict[str, float] = {node: float("inf") for node in graph}
    prev: dict[str, str | None] = {node: None for node in graph}
    distances[src] = 0

    queue: list[tuple[float, str]] = [(0, src)]
    visited: set[str] = set()

    while queue:
        distance, neighbor = heapq.heappop(queue)
        if neighbor in visited:
            continue

        visited.add(neighbor)

        if neighbor == dest:
            break

        for node, weight in graph[neighbor].items():
            if node in visited:
                continue

            new_distance: float = distance + weight
            if new_distance < distances[node]:
                distances[node] = new_distance
                prev[node] = neighbor
                heapq.heappush(queue, (new_distance, node))

    if distances[dest] == float("inf"):
        return []

    path: list[str] = []
    current: str | None = dest
    while current is not None:
        path.append(current)
        current = prev[current]

    path.reverse()
    return path


def dfs_path(graph: Graph, src: str, dest: str) -> list[str]:
    stack: list[tuple[str, list[str], float]] = [(src, [src], 0)]
    best_path: list[str] = []
    best_cost: float = float("inf")

    while stack:
        current_node, path, current_cost = stack.pop()

        if current_node == dest:
            if current_cost < best_cost:
                best_cost = current_cost
                best_path = path.copy()

            continue

        if current_cost >= best_cost:
            continue

        for neighbor in graph[current_node]:
            if neighbor not in path:
                new_path: list[str] = path + [neighbor]
                new_cost: float = current_cost + graph[current_node][neighbor]
                stack.append((neighbor, new_path, new_cost))

    return best_path

